import{_ as a,o as s,c as i,a2 as l}from"./chunks/framework.1lR7qgqY.js";const k=JSON.parse('{"title":"第 8 章 第一次在本機執行模型","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/08-first-run.md","filePath":"deploy/08-first-run.md","lastUpdated":1793002104000}'),d={name:"deploy/08-first-run.md"};function e(o,t,r,h,n,p){return s(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="第-8-章-第一次在本機執行模型" tabindex="-1">第 8 章 第一次在本機執行模型 <a class="header-anchor" href="#第-8-章-第一次在本機執行模型" aria-label="Permalink to &quot;第 8 章 第一次在本機執行模型&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (指令未實機驗證)</li><li>資料基準日: 2026-10-26</li><li>待查證: 本章所有指令依官方文件整理, 尚未在實機執行; llama.cpp 與 LM Studio 的操作步驟本輪未核對, 僅列定位; 標示「推論」的段落未有官方文件依據</li></ul></div><p><strong>結論</strong>: 初階讀者以 Ollama 完成第一次對話最快: 安裝, 執行一行指令, 即可開始. 完成後再依<a href="/docs-handbook-poc/deploy/09-architectures">第 9 章</a>加上介面. 本章也整理上線前常被略過的五件事: GPU 驅動確認, 模型下載驗證, 離線安裝, 日誌, 以及參數調校.</p><h2 id="_8-1-ollama-llama-cpp-與-lm-studio-的選擇" tabindex="-1">8.1 Ollama, llama.cpp 與 LM Studio 的選擇 <a class="header-anchor" href="#_8-1-ollama-llama-cpp-與-lm-studio-的選擇" aria-label="Permalink to &quot;8.1 Ollama, llama.cpp 與 LM Studio 的選擇&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>定位</th><th>適用讀者</th><th>本章是否提供步驟</th></tr></thead><tbody><tr><td>Ollama</td><td>命令列加背景服務, 內建模型下載與管理</td><td>初階到中階, 想最快開始</td><td>是</td></tr><tr><td>llama.cpp (llama-server)</td><td>底層推論引擎, 可調參數最多</td><td>想精細控制, 或搭配 llama-swap 者</td><td>否 (未核對, 請讀官方文件)</td></tr><tr><td>LM Studio</td><td>桌面圖形介面</td><td>不想用命令列者</td><td>否 (未核對, 請讀官方文件)</td></tr></tbody></table><p>以上定位為整理者的歸納 (信心: 中). 版本資訊見<a href="/docs-handbook-poc/ref/versions">版本頁</a>.</p><h2 id="_8-2-用-ollama-完成第一次對話" tabindex="-1">8.2 用 Ollama 完成第一次對話 <a class="header-anchor" href="#_8-2-用-ollama-完成第一次對話" aria-label="Permalink to &quot;8.2 用 Ollama 完成第一次對話&quot;">​</a></h2><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to &quot;安裝&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系統</th><th>做法</th><th>系統需求 (來源: Ollama 文件)</th></tr></thead><tbody><tr><td>macOS</td><td>下載 <code>ollama.dmg</code>, 把應用程式拖曳到「應用程式」資料夾</td><td>macOS Sonoma (v14) 以上; Apple M 系列可用 GPU, x86 僅 CPU</td></tr><tr><td>Windows</td><td>執行 <code>OllamaSetup.exe</code>, 不需要系統管理員權限</td><td>Windows 10 22H2 以上; 二進位安裝至少 4GB 磁碟空間; NVIDIA 驅動 551.61 以上</td></tr><tr><td>Linux</td><td><code>curl -fsSL https://ollama.com/install.sh | sh</code></td><td>見 8.4 節</td></tr></tbody></table><p>Linux 的一行安裝指令會直接執行從網路下載的腳本. 受管制的環境, 建議改用 8.6 節的手動安裝, 並先檢視內容.</p><h3 id="第一次對話" tabindex="-1">第一次對話 <a class="header-anchor" href="#第一次對話" aria-label="Permalink to &quot;第一次對話&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">模型名</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">稱</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span></span></code></pre></div><p>指令會先下載模型, 再進入對話; 輸入 <code>/bye</code> 離開 (來源: Ollama 文件 Quickstart). 模型名稱請從 Ollama 官方模型庫 (ollama.com 網站) 選擇, 並依<a href="/docs-handbook-poc/select/05-quantization">第 5 章</a>確認記憶體放得下.</p><h3 id="常用管理指令" tabindex="-1">常用管理指令 <a class="header-anchor" href="#常用管理指令" aria-label="Permalink to &quot;常用管理指令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指令</th><th>用途</th></tr></thead><tbody><tr><td><code>ollama pull &lt;模型名稱&gt;</code></td><td>只下載, 不進入對話</td></tr><tr><td><code>ollama ls</code></td><td>列出已下載的模型</td></tr><tr><td><code>ollama ps</code></td><td>列出執行中的模型</td></tr><tr><td><code>ollama stop &lt;模型名稱&gt;</code></td><td>停止執行中的模型</td></tr><tr><td><code>ollama rm &lt;模型名稱&gt;</code></td><td>移除模型</td></tr><tr><td><code>ollama serve</code></td><td>啟動服務</td></tr></tbody></table><p>來源: Ollama 文件 CLI reference.</p><h3 id="確認服務可用" tabindex="-1">確認服務可用 <a class="header-anchor" href="#確認服務可用" aria-label="Permalink to &quot;確認服務可用&quot;">​</a></h3><p>Ollama 預設只綁定 <code>127.0.0.1</code> 的 11434 連接埠 (來源: Ollama FAQ). 下列指令可確認 API 回應 (範例格式依 Ollama 文件的 <code>/api/generate</code> 用法, 欄位以官方文件為準):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> http://localhost:11434/api/generate</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> &#39;{&quot;model&quot;: &quot;&lt;模型名稱&gt;&quot;, &quot;prompt&quot;: &quot;你好&quot;, &quot;stream&quot;: false}&#39;</span></span></code></pre></div><h2 id="_8-3-確認安裝結果的最短檢核" tabindex="-1">8.3 確認安裝結果的最短檢核 <a class="header-anchor" href="#_8-3-確認安裝結果的最短檢核" aria-label="Permalink to &quot;8.3 確認安裝結果的最短檢核&quot;">​</a></h2><ul><li>[ ] <code>ollama -v</code> 顯示版本 (Linux 手動安裝頁面以此驗證), 並記錄到版本紀錄 (<a href="/docs-handbook-poc/ops/19-versioning">第 19 章</a>)</li><li>[ ] <code>ollama run</code> 能完成一次回答</li><li>[ ] 回答時查看 GPU 使用量 (NVIDIA 可用 <code>nvidia-smi</code>), 確認模型確實在 GPU 上</li><li>[ ] 其他裝置無法連到 11434 連接埠 (尚未打算對外開放時)</li></ul><h2 id="_8-4-gpu-驅動確認" tabindex="-1">8.4 GPU 驅動確認 <a class="header-anchor" href="#_8-4-gpu-驅動確認" aria-label="Permalink to &quot;8.4 GPU 驅動確認&quot;">​</a></h2><p>沒有確認驅動, 模型會悄悄退回 CPU 執行, 速度差距很大, 又不容易察覺 (信心: 高, 屬一般經驗).</p><table tabindex="0"><thead><tr><th>平台</th><th>條件</th><th>確認方式</th></tr></thead><tbody><tr><td>NVIDIA</td><td>運算能力 5.0 以上, 驅動 550 以上; 運算能力 5.0 至 6.2 的舊卡須驅動 570 以上; Windows 需 551.61 以上</td><td><code>nvidia-smi</code> 能列出顯示卡</td></tr><tr><td>AMD (Linux)</td><td>ROCm v7 驅動; 另需下載 ROCm 套件</td><td>依 AMD 文件; Ollama 頁面未提供驗證指令</td></tr><tr><td>AMD (Windows)</td><td>支援 ROCm v7 / HIP7 的驅動, 或支援 Vulkan 的 Radeon 驅動</td><td>依 AMD 文件</td></tr><tr><td>Apple Silicon</td><td>透過 Metal API 提供 GPU 加速</td><td>無需額外驅動</td></tr></tbody></table><p>來源: Ollama 文件 GPU support, Linux, Windows.</p><p><strong>排除方式</strong> (來源: Ollama 文件 Troubleshooting 與 GPU support):</p><ol><li>用容器執行時, 先測試 <code>docker run --gpus all ubuntu nvidia-smi</code>. 這個測試失敗, Ollama 也看不到 NVIDIA 顯示卡.</li><li>Linux 在休眠喚醒後找不到 GPU 時, 官方提供的暫時解法是重新載入驅動模組: <code>sudo rmmod nvidia_uvm &amp;&amp; sudo modprobe nvidia_uvm</code>.</li><li>設定 <code>OLLAMA_DEBUG=1</code> 後, GPU 偵測期間會輸出額外資訊.</li><li>多張顯示卡時, 以 <code>CUDA_VISIBLE_DEVICES</code> 指定使用的卡; 官方建議用 UUID 而非數字編號, UUID 可用 <code>nvidia-smi -L</code> 查詢.</li></ol><h2 id="_8-5-模型下載與驗證" tabindex="-1">8.5 模型下載與驗證 <a class="header-anchor" href="#_8-5-模型下載與驗證" aria-label="Permalink to &quot;8.5 模型下載與驗證&quot;">​</a></h2><p>模型檔是第三方提供的大型二進位資料, 下載後應確認「檔案完整」與「來源可信」兩件事, 兩者不同 (信心: 高).</p><table tabindex="0"><thead><tr><th>驗證事項</th><th>做法</th></tr></thead><tbody><tr><td>來源可信</td><td>只從官方組織帳號或知名發布者下載; 確認授權 (見<a href="/docs-handbook-poc/ref/licenses">授權速查</a>); 優先 safetensors 或 GGUF, 避免來源不明的 pickle 檔</td></tr><tr><td>版本可追溯</td><td>下載時指定 revision (commit hash), 不使用會變動的 main</td></tr><tr><td>檔案完整</td><td>比對校驗碼</td></tr></tbody></table><p><strong>Hugging Face 的做法</strong> (來源: Hugging Face 文件 CLI guide):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># 下載指定檔案, 並指定 revision</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">hf</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> download</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">組織/模型</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">庫</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">檔</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --revision</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">commit</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> has</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># 驗證本機快取的檔案與 Hub 上的校驗碼是否一致</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">hf</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> cache</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> verify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">組織/模型</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">庫</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">&gt;</span></span></code></pre></div><p>全部相符時會顯示 <code>All checksums match.</code>; 有不符時會列出清單並以非零狀態碼結束. 預設只對缺少或多餘的檔案發出警告, 要視為錯誤須加 <code>--fail-on-missing-files --fail-on-extra-files</code>.</p><p>注意: 校驗碼比對只證明「和 Hub 上的一致」, 不證明發布者可信.</p><p><strong>登記表</strong>: 每個模型記錄下列欄位, 之後回退或稽核時才查得到.</p><table tabindex="0"><thead><tr><th>欄位</th><th>範例</th></tr></thead><tbody><tr><td>模型庫與檔名</td><td></td></tr><tr><td>revision (commit hash)</td><td></td></tr><tr><td>下載日期</td><td></td></tr><tr><td>授權</td><td></td></tr><tr><td>校驗結果</td><td></td></tr><tr><td>使用者與用途</td><td></td></tr></tbody></table><p><strong>匯入 Ollama</strong>: 本機的 GGUF 檔以 Modelfile 匯入. Modelfile 內寫 <code>FROM /path/to/file.gguf</code>, 再執行 <code>ollama create &lt;名稱&gt;</code> (來源: Ollama 文件 Import).</p><h2 id="_8-6-離線安裝" tabindex="-1">8.6 離線安裝 <a class="header-anchor" href="#_8-6-離線安裝" aria-label="Permalink to &quot;8.6 離線安裝&quot;">​</a></h2><p>適用於不能連網的環境. 以下步驟中, 標示「推論」者尚未有官方文件說明, 請先在測試環境確認.</p><p><strong>準備 (在可連網的機器)</strong>:</p><ol><li><strong>Ollama 程式</strong>: Linux 下載 <code>ollama-linux-amd64.tar.zst</code> (AMD 另需 <code>ollama-linux-amd64-rocm.tar.zst</code>); Windows 下載 <code>OllamaSetup.exe</code>; macOS 下載 <code>ollama.dmg</code> (來源: Ollama 文件各平台頁).</li><li><strong>模型</strong>: 兩種做法. <ul><li>在可連網機器 <code>ollama pull</code> 後, 複製模型目錄到離線機器. 模型目錄位置: macOS <code>~/.ollama/models</code>, Linux <code>/usr/share/ollama/.ollama/models</code>, Windows <code>C:\\Users\\%username%\\.ollama\\models</code>, 可用 <code>OLLAMA_MODELS</code> 指定 (來源: Ollama FAQ). 直接複製目錄是否可用屬推論, 信心: 中.</li><li>下載 GGUF 檔, 在離線機器用 Modelfile 匯入 (見 8.5 節).</li></ul></li><li><strong>容器映像</strong>: 在可連網機器用 <code>docker pull</code> 取得固定版本映像, 再以 <code>docker save</code> 匯出, 離線機器以 <code>docker load</code> 匯入 (Docker 指令的通用做法, 未實機驗證).</li><li><strong>校驗碼</strong>: 為每個檔案產生 SHA-256, 複製到離線機器後重新計算並比對 (如 <code>sha256sum</code>).</li></ol><p><strong>Linux 手動安裝</strong> (來源: Ollama 文件 Linux):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> tar</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> x</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> /usr</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ollama-linux-amd64.tar.zst</span><span style="--shiki-light:#6A737D;--shiki-dark:#768390;">   # 解壓縮到 /usr (指令形式為依官方範例改寫)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> useradd</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> /bin/</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">false</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -U</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> /usr/share/ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ollama</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ollama</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">whoami</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">)</span></span></code></pre></div><p>之後依官方頁面建立 <code>/etc/systemd/system/ollama.service</code>, 執行 <code>sudo systemctl daemon-reload</code> 與 <code>sudo systemctl enable ollama</code>. 官方頁面的壓縮格式為 <code>.tar.zst</code>, 離線機器須有支援 zstd 的 tar.</p><p><strong>離線環境的注意事項</strong>:</p><ul><li>Open WebUI 的內建檢索功能首次使用時, 可能需要下載嵌入模型. 離線環境請事先確認並預先放入 (未驗證).</li><li>離線環境的更新流程相同, 只是改由可移除媒體傳遞. 更新前仍要備份並跑測試集 (<a href="/docs-handbook-poc/ops/19-versioning">第 19 章</a>).</li><li>傳入媒體先掃毒, 並保留校驗碼清單.</li></ul><h2 id="_8-7-日誌" tabindex="-1">8.7 日誌 <a class="header-anchor" href="#_8-7-日誌" aria-label="Permalink to &quot;8.7 日誌&quot;">​</a></h2><p>出問題時, 日誌是第一個要看的地方. 位置如下 (來源: Ollama 文件 Troubleshooting):</p><table tabindex="0"><thead><tr><th>環境</th><th>查看方式</th></tr></thead><tbody><tr><td>macOS</td><td><code>cat ~/.ollama/logs/server.log</code></td></tr><tr><td>Linux (systemd)</td><td><code>journalctl -u ollama --no-pager --follow --pager-end</code></td></tr><tr><td>Docker 容器</td><td><code>docker logs &lt;container-name&gt;</code></td></tr><tr><td>手動執行 <code>ollama serve</code></td><td>日誌顯示在該終端機</td></tr><tr><td>Windows</td><td>檔案總管開啟 <code>%LOCALAPPDATA%\\Ollama</code>, 最新的是 <code>server.log</code></td></tr></tbody></table><p><strong>維運建議</strong> (信心: 中, 屬一般經驗):</p><ul><li>記錄日誌的保留期間與磁碟占用, 避免日誌塞滿磁碟.</li><li>先確認日誌是否含有對話內容, 再決定存取權限與保留天數 (本輪未驗證 Ollama 與介面的日誌內容).</li><li>每週檢查時順便掃一次錯誤訊息, 特別是 GPU 偵測失敗與記憶體不足.</li><li>需要更多資訊時才開啟 <code>OLLAMA_DEBUG=1</code>, 事後關閉.</li></ul><h2 id="_8-8-參數調校" tabindex="-1">8.8 參數調校 <a class="header-anchor" href="#_8-8-參數調校" aria-label="Permalink to &quot;8.8 參數調校&quot;">​</a></h2><p>Ollama 以環境變數設定. 預設值與用途如下 (來源: Ollama FAQ):</p><table tabindex="0"><thead><tr><th>環境變數</th><th>預設值</th><th>用途與調整原則</th></tr></thead><tbody><tr><td><code>OLLAMA_HOST</code></td><td><code>127.0.0.1:11434</code></td><td>綁定位址. 改成 <code>0.0.0.0</code> 會開放給其他裝置, 僅在有防火牆與存取控制時才做</td></tr><tr><td><code>OLLAMA_CONTEXT_LENGTH</code></td><td>4096</td><td>上下文長度. 加大會增加記憶體占用 (見第 5.3 節)</td></tr><tr><td><code>OLLAMA_NUM_PARALLEL</code></td><td>1</td><td>每個模型同時處理的請求數. 所需記憶體隨它與上下文長度的乘積增加</td></tr><tr><td><code>OLLAMA_MAX_LOADED_MODELS</code></td><td>GPU 數量 x 3 (CPU 推論為 3)</td><td>可同時載入的模型數</td></tr><tr><td><code>OLLAMA_MAX_QUEUE</code></td><td>512</td><td>忙碌時的排隊上限, 超過時回應 503</td></tr><tr><td><code>OLLAMA_MODELS</code></td><td>見 8.6 節</td><td>模型存放目錄; Linux 標準安裝須讓 <code>ollama</code> 使用者有讀寫權限: <code>sudo chown -R ollama:ollama &lt;directory&gt;</code></td></tr></tbody></table><p><strong>Linux 以 systemd 設定環境變數</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> edit</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ollama.service</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># 在 [Service] 區段加入, 例如:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;">#   Environment=&quot;OLLAMA_CONTEXT_LENGTH=8192&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> ollama</span></span></code></pre></div><p><strong>調校順序</strong> (信心: 中, 屬推論): 先用預設值跑通; 只在實際需要時調整一項, 並用<a href="/docs-handbook-poc/apply/14-evaluation">第 14 章</a>測試集與耗時記錄比較前後差異; 一次只改一項, 才知道哪個變動有效.</p><p>macOS 的環境變數設定方式, Ollama 文件頁面未說明, 本輪未核對.</p><h2 id="_8-9-常見錯誤排除" tabindex="-1">8.9 常見錯誤排除 <a class="header-anchor" href="#_8-9-常見錯誤排除" aria-label="Permalink to &quot;8.9 常見錯誤排除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現象</th><th>可能原因</th><th>處理</th></tr></thead><tbody><tr><td>載入失敗或速度極慢</td><td>記憶體不足, 模型退回 CPU</td><td>換較小的模型或量化, 或降低上下文 (第 5 章); 確認 GPU (8.4 節)</td></tr><tr><td>下載中斷</td><td>網路不穩</td><td>重新執行 <code>ollama pull</code>; Hugging Face 中斷留下的 <code>.incomplete</code> 檔可用 <code>hf cache prune</code> 清除</td></tr><tr><td>連接埠被占用</td><td>11434 已有其他程式</td><td>Linux 可用 <code>ss -ltnp</code> 查詢占用的程式 (通用指令, 未驗證)</td></tr><tr><td>回應 503</td><td>排隊已滿</td><td>檢視 <code>OLLAMA_MAX_QUEUE</code> 與使用人數</td></tr><tr><td>模型目錄權限錯誤</td><td><code>ollama</code> 使用者無權限</td><td><code>sudo chown -R ollama:ollama &lt;directory&gt;</code></td></tr><tr><td>休眠後改用 CPU</td><td>NVIDIA 驅動模組狀態異常</td><td>見 8.4 節</td></tr></tbody></table><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><a href="https://docs.ollama.com/faq" target="_blank" rel="noreferrer">Ollama 文件: FAQ</a></li><li><a href="https://docs.ollama.com/quickstart" target="_blank" rel="noreferrer">Ollama 文件: Quickstart</a></li><li><a href="https://docs.ollama.com/cli" target="_blank" rel="noreferrer">Ollama 文件: CLI reference</a></li><li><a href="https://docs.ollama.com/linux" target="_blank" rel="noreferrer">Ollama 文件: Linux</a></li><li><a href="https://docs.ollama.com/windows" target="_blank" rel="noreferrer">Ollama 文件: Windows</a></li><li><a href="https://docs.ollama.com/macos" target="_blank" rel="noreferrer">Ollama 文件: macOS</a></li><li><a href="https://docs.ollama.com/gpu" target="_blank" rel="noreferrer">Ollama 文件: GPU support</a></li><li><a href="https://docs.ollama.com/troubleshooting" target="_blank" rel="noreferrer">Ollama 文件: Troubleshooting</a></li><li><a href="https://docs.ollama.com/import" target="_blank" rel="noreferrer">Ollama 文件: Import</a></li><li><a href="https://huggingface.co/docs/huggingface_hub/guides/cli" target="_blank" rel="noreferrer">Hugging Face 文件: CLI guide</a></li></ul>`,62)])])}const m=a(d,[["render",e]]);export{k as __pageData,m as default};
